import Foundation

/// Stops, routes, line geometry and Luas patterns bundled with the app
/// (generated by tools/build_static_data.py).
nonisolated struct StaticData: Sendable {
    let stops: [Stop]
    let stopsById: [String: Stop]
    /// Stops drawn on the map and offered in search: Luas platforms are
    /// collapsed to one pin per station.
    let displayStops: [Stop]
    let routes: [String: RouteInfo]
    let lines: [LineShape]
    let luas: LuasSchedule
    /// Route + direction pairs that call at each stop.
    let stopRoutes: [String: [RouteDirection]]

    static let empty = StaticData(stops: [], routes: [:], lines: [], luas: LuasSchedule(patterns: [], trips: [:]), stopRoutes: [:])

    init(stops: [Stop], routes: [String: RouteInfo], lines: [LineShape], luas: LuasSchedule,
         stopRoutes: [String: [RouteDirection]]) {
        self.stops = stops
        self.routes = routes
        self.lines = lines
        self.luas = luas
        self.stopRoutes = stopRoutes
        stopsById = Dictionary(stops.map { ($0.id, $0) }, uniquingKeysWith: { first, _ in first })

        var seenLuas = Set<String>()
        displayStops = stops.filter { stop in
            guard stop.mode == .luas, let code = stop.luasCode else { return true }
            return seenLuas.insert(code).inserted
        }
    }

    @concurrent
    static func loadFromBundle(_ bundle: Bundle = .main) async throws -> StaticData {
        func load<T: Decodable>(_ name: String, as type: T.Type) throws -> T {
            guard let url = bundle.url(forResource: name, withExtension: "json") else {
                throw CocoaError(.fileNoSuchFile, userInfo: [NSFilePathErrorKey: "\(name).json"])
            }
            return try JSONDecoder().decode(T.self, from: Data(contentsOf: url))
        }
        return StaticData(
            stops: try load("stops", as: [Stop].self),
            routes: try load("routes", as: [String: RouteInfo].self),
            lines: try load("lines", as: [LineShape].self),
            luas: try load("luas", as: LuasSchedule.self),
            stopRoutes: try load("stop_routes", as: [String: [RouteDirection]].self)
        )
    }

    /// All platform IDs belonging to the same station as `stop` (Luas has one per direction).
    func siblingStopIds(of stop: Stop) -> Set<String> {
        guard stop.mode == .luas, let code = stop.luasCode else { return [stop.id] }
        return Set(stops.filter { $0.luasCode == code }.map(\.id))
    }

    /// Every route + direction calling at `stop` (or any platform of its station).
    func routesServing(_ stop: Stop) -> Set<RouteDirection> {
        Set(siblingStopIds(of: stop).flatMap { stopRoutes[$0] ?? [] })
    }
}

/// Encoded in stop_routes.json as a `[route_id, direction_id]` pair.
nonisolated struct RouteDirection: Hashable, Sendable, Decodable {
    let routeId: String
    let directionId: Int

    init(routeId: String, directionId: Int) {
        self.routeId = routeId
        self.directionId = directionId
    }

    init(from decoder: Decoder) throws {
        var container = try decoder.unkeyedContainer()
        routeId = try container.decode(String.self)
        directionId = try container.decode(Int.self)
    }
}
